const crypto = require('crypto');

function base64UrlDecode(input) {
  input = input.replace(/-/g, '+').replace(/_/g, '/');
  while (input.length % 4) {
    input += '=';
  }
  return Buffer.from(input, 'base64');
}

function base64UrlEncode(buffer) {
  return buffer.toString('base64').replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/g, '');
}

function verifyHs256(token, secret) {
  const parts = token.split('.');
  if (parts.length !== 3) {
    return { valid: false, error: 'invalid token format' };
  }
  const [encodedHeader, encodedPayload, signature] = parts;
  let header;
  let payload;
  try {
    header = JSON.parse(base64UrlDecode(encodedHeader).toString('utf8'));
    payload = JSON.parse(base64UrlDecode(encodedPayload).toString('utf8'));
  } catch (err) {
    return { valid: false, error: 'invalid token payload' };
  }
  if (header.alg !== 'HS256') {
    return { valid: false, error: 'unsupported algorithm' };
  }
  const hmac = crypto.createHmac('sha256', secret);
  hmac.update(`${encodedHeader}.${encodedPayload}`);
  const expected = base64UrlEncode(hmac.digest());
  let providedBuffer;
  let expectedBuffer;
  try {
    providedBuffer = base64UrlDecode(signature);
    expectedBuffer = base64UrlDecode(expected);
  } catch (err) {
    return { valid: false, error: 'invalid token signature' };
  }
  if (providedBuffer.length !== expectedBuffer.length) {
    return { valid: false, error: 'invalid token signature' };
  }
  if (!crypto.timingSafeEqual(providedBuffer, expectedBuffer)) {
    return { valid: false, error: 'invalid token signature' };
  }
  return { valid: true, header, payload };
}

function buildError(responseCode, message) {
  return [{
    json: {
      branch: 'error',
      responseCode,
      response: { error: message },
    },
  }];
}

function signLink(url, userId, secret, ttlSec = 300) {
  const exp = Math.floor(Date.now() / 1000) + ttlSec;
  const payload = `${userId}.${exp}.${url}`;
  const sig = crypto.createHmac('sha256', secret).update(payload).digest('base64');
  const signature = sig.replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/g, '');
  const link = new URL(url);
  link.searchParams.set('uid', userId);
  link.searchParams.set('exp', exp);
  link.searchParams.set('sig', signature);
  return { url: link.toString(), expiresAt: exp };
}

const request = items[0].json ?? {};
const body = (request.body && typeof request.body === 'object') ? request.body : request;
const headers = (request.headers && typeof request.headers === 'object') ? request.headers : {};
const normalizedHeaders = Object.fromEntries(Object.entries(headers).map(([key, value]) => [key.toLowerCase(), value]));

const ipWhitelist = ($env.N8N_LEAVE_IP_WHITELIST || '')
  .split(',')
  .map((value) => value.trim())
  .filter(Boolean);

const sourceIp = (normalizedHeaders['x-forwarded-for'] || '').split(',')[0].trim();
if (ipWhitelist.length > 0 && (!sourceIp || !ipWhitelist.includes(sourceIp))) {
  return buildError(403, 'ip_not_allowed');
}

const authHeader = normalizedHeaders.authorization;
if (!authHeader) {
  return buildError(401, 'missing_authorization');
}

const tokenMatch = authHeader.match(/^bearer\s+(.+)$/i);
if (!tokenMatch) {
  return buildError(401, 'invalid_authorization_format');
}

const token = tokenMatch[1].trim();
const jwtSecret = $env.N8N_LEAVE_JWT_SECRET;
if (!jwtSecret) {
  throw new Error('N8N_LEAVE_JWT_SECRET not configured');
}

const verification = verifyHs256(token, jwtSecret);
if (!verification.valid) {
  return buildError(401, verification.error || 'invalid_token');
}

const jwtPayload = verification.payload;
const now = Math.floor(Date.now() / 1000);
if (jwtPayload.exp && jwtPayload.exp < now) {
  return buildError(401, 'token_expired');
}

const allowedIssuers = ($env.N8N_LEAVE_JWT_ISS || '')
  .split(',')
  .map((value) => value.trim())
  .filter(Boolean);
if (allowedIssuers.length > 0 && jwtPayload.iss && !allowedIssuers.includes(jwtPayload.iss)) {
  return buildError(401, 'unauthorized_issuer');
}

const allowedAudiences = ($env.N8N_LEAVE_JWT_AUD || '')
  .split(',')
  .map((value) => value.trim())
  .filter(Boolean);
if (allowedAudiences.length > 0 && jwtPayload.aud && !allowedAudiences.includes(jwtPayload.aud)) {
  return buildError(401, 'unauthorized_audience');
}

const { userId, org, intent, type, locale, ts } = body;
if (!userId || !intent) {
  return buildError(400, 'missing_userId_or_intent');
}

const normalizedIntent = String(intent).toLowerCase();
const normalizedType = type ? String(type).toLowerCase() : '';
const branchKey = normalizedType ? `${normalizedIntent}_${normalizedType}` : normalizedIntent;

const BASE = {
  leave_annual: 'https://hr.example.com/leave/annual',
  leave_sick: 'https://hr.example.com/leave/sick',
  leave_marriage: 'https://hr.example.com/leave/marriage',
  leave_bereavement: 'https://hr.example.com/leave/bereavement',
  business_trip: 'https://hr.example.com/travel/start',
};

const ORG_BASE = {
  'SZ-OPS': {
    leave_annual: 'https://hr.sz.example.com/leave/annual',
  },
};

const TITLES = {
  leave_annual: '申请年假',
  leave_sick: '申请病假',
  leave_marriage: '申请婚假',
  leave_bereavement: '申请丧假',
  business_trip: '去出差办事',
};

const baseByOrg = ORG_BASE[org] ? { ...BASE, ...ORG_BASE[org] } : BASE;

let url = baseByOrg[branchKey] || baseByOrg[normalizedIntent];
if (!url) {
  return buildError(422, 'unsupported_intent');
}

const traceId = crypto.randomBytes(6).toString('hex');

const link = new URL(url);
link.searchParams.set('src', 'fastbuild-ai');
link.searchParams.set('trace', traceId);
if (locale) {
  link.searchParams.set('locale', locale);
}
if (ts) {
  link.searchParams.set('ts', String(ts));
}

link.searchParams.set('utm_source', 'fastbuild-ai');
link.searchParams.set('utm_medium', 'assistant');
link.searchParams.set('utm_campaign', normalizedIntent);

const linkSecret = $env.N8N_LINK_SIGN_SECRET || $env.N8N_LEAVE_LINK_SIGN_SECRET;
if (!linkSecret) {
  throw new Error('N8N_LINK_SIGN_SECRET not configured');
}

const ttlSec = Number($env.N8N_LEAVE_LINK_TTL || '300');
const signed = signLink(link.toString(), userId, linkSecret, ttlSec);

return [{
  json: {
    branch: branchKey,
    responseCode: 200,
    response: {
      title: TITLES[branchKey] || TITLES[normalizedIntent] || '去办理',
      url: signed.url,
      traceId,
      expiresAt: signed.expiresAt,
    },
  },
}];
